INSERT INTO `announcements` (`announcement_id`, `title`, `location`, `content`, `category`, `is_event`, `event_date`, `event_end_date`, `event_start_time`, `event_end_time`, `venue_provider`, `venue_name`, `response_deadline`, `subject`, `announcement_type`, `priority`, `photo_url`, `photo_hover_url`, `link_url`, `barangay_id`, `program_id`, `audience_type`, `audience_barangays`, `is_featured`, `created_by`, `created_at`, `updated_at`, `facebook_posting_mode`, `facebook_opt_out`, `expiry_date`, `status`, `publish_at`, `archived_at`, `is_active`) VALUES
(30, 'Free Kapon Caravan for Dogs and Cats', 'Paliparan 3', 'The Dasmariñas City Veterinary Services invites pet owners to participate in our upcoming Free Kapon Caravan for dogs and cats in Paliparan 3, Dasmariñas City. This upcoming weekend October 13, 2026 l 8:00 AM', 'announcement', 1, '2026-10-12', NULL, '08:00:00', '17:00:00', 'barangay_venue', 'covered court', '2026-10-12 07:40:00', 'events', 'general', 'medium', 'uploads/announcements/ann_photo_6acb9ffa69185.jpg', NULL, '', NULL, NULL, 'selected', '', 0, 14, '2026-10-11 14:40:58', '2026-10-11 17:18:14', 'automatic', 0, NULL, 'published', '2026-10-11 22:39:00', NULL, 1),
(33, 'Free Anti-Rabies Vaccination Drive for Dogs and Cats', 'Paliparan I, Salawag', 'The Dasmariñas City Veterinary Services (DCVS) invites all pet owners to join our Free Anti-Rabies Vaccination Drive for dogs and cats! 🐶 Who can participate? Residents with dogs and cats eligible for anti-rabies vaccination.\r\n\r\n📋 Reminders for pet owners:\r\n\r\nKeep your pets secured and properly restrained during the activity.\r\n\r\nBring your pet\'s vaccination record, if available.\r\n\r\nEnsure that your pet is accompanied by its owner or a responsible adult.', 'announcement', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'general_notices', 'general', 'medium', 'uploads/announcements/ann_photo_6acf9c4d81c39.jpg', NULL, '', NULL, NULL, 'all', '', 0, 14, '2026-10-14 15:14:21', '2026-10-14 15:14:21', 'automatic', 0, NULL, 'published', NULL, NULL, 1),
(35, 'Free Pet Spay and Neuter Program', 'Burol Main, Langkaan I', 'The Dasmariñas City Veterinary Services (DCVS) announces a Free Pet Spay and Neuter Program for eligible dogs and cats in the community! YAHOOOO\r\n\r\n📅 Date: October 30, 2026 (Friday)\r\n⏰ Time: 8:00 AM – 3:00 PM\r\n📍 Location: Burol Main and Langkaan I Barangay Halls\r\n\r\nThis program aims to promote responsible pet ownership, help manage the pet population, and improve animal welfare throughout Dasmariñas.', 'announcement', 1, '2026-10-20', NULL, '08:30:00', '15:00:00', 'barangay_venue', 'covered court', '2026-10-19 01:56:00', 'events', 'general', 'medium', 'uploads/announcements/ann_photo_6ad4b7a4ea9e5.jpg', NULL, '', NULL, NULL, 'selected', '', 0, 14, '2026-10-18 12:12:20', '2026-10-23 15:43:30', 'automatic', 0, NULL, 'published', NULL, NULL, 1);
