(101, 'jcffornal@kld.edu.ph', 'Chloe Fornal', 'Verify Your DCVS Password Reset Request', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n</head>\n<body style=\"margin:0;padding:0;background-color:#ffffff;font-family:\'Inter\',\'Segoe UI\',Helvetica,Arial,sans-serif;color:#0f172a;font-size:16px;line-height:1.6;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#ffffff;\">\n<tr><td style=\"padding:28px 24px 20px;\">\n  <p style=\"margin:0 0 20px;font-size:20px;font-weight:700;color:#0f172a;letter-spacing:-0.02em;line-height:1.3;\">Verify Request</p>\n  <p style=\"margin:0 0 16px;\">Dear <strong>Chloe Fornal</strong>,</p><p style=\"margin:0 0 16px;\">We received a request to reset your DCVS account password.</p><p style=\"margin:0 0 16px;\">If this was you, click the button below to verify your request and proceed with resetting your password.</p><p style=\"margin:20px 0;\"><a href=\"http://192.168.18.143/dcvs/verify-request.php?token=3c6b0a49e502b74958002e0864df512c711376318d751d4f1a5f79cd49ecab9d\" style=\"display:inline-block;background:#18181b;color:#fafafa;padding:10px 20px;border-radius:6px;font-family:Inter,Helvetica,Arial,sans-serif;font-size:14px;font-weight:500;text-decoration:none;\">Verify Request</a></p><p style=\"margin:0 0 8px;font-size:13px;color:#64748b;\">If you didn&rsquo;t request a password reset, you can safely ignore this email. Your password will remain unchanged.</p><p style=\"margin:0;font-size:12px;color:#94a3b8;\">This verification link will expire in <strong>15 minutes</strong>.</p>\n  \n</td></tr>\n</table>\n</body>\n</html>', 'sent', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, '2026-09-22 09:49:07'),
